#!/usr/bin/env python3
"""Gate C11 phase 4: write results/analysis/gate_e/GATE_H2_REPORT.md, the two figures (+ CSV fallbacks) and consolidation/CS2_N12_PROPOSED.md from the committed
h2_tests.csv, h2_residency_cells.csv, h2_z.csv, h2_runs.csv and residency_summary.csv. Every number comes from those CSVs (evidence ids H2.* are generated by tests/c1_evidence.py)."""
import csv, os, statistics as st, sys
sys.path.insert(0, "tests")
import h2_cells as C
D = "results/analysis/gate_e/h2"
rd = lambda p: list(csv.DictReader(open(p)))   # noqa: E731
T, RC, Z, RUNS, RES = rd(f"{D}/h2_tests.csv"), rd(f"{D}/h2_residency_cells.csv"), rd(f"{D}/h2_z.csv"), rd(f"{D}/h2_runs.csv"), rd(f"{D}/residency_summary.csv")
verdict = next(r["outcome"] for r in Z if r["id"] == "verdict")
TT = {(t["alloc"], int(t["K"])): t for t in T}
m = len(T); order = sorted(range(m), key=lambda i: float(T[i]["p"])); adj = [None] * m; run = 0.0
for rank, i in enumerate(order):
    run = max(run, min(1.0, (m - rank) * float(T[i]["p"]))); adj[i] = run
ADJ = {(T[i]["alloc"], int(T[i]["K"])): adj[i] for i in range(m)}
GB = 8192.0
out = ["# Gate H2 - Report: the sparse-access cost of threshold 0 on HMM vs managed memory (in memory only)", "",
       f"## Verdict (mechanical, `H2_PREREGISTRATION.md`): {verdict}", "",
       "Pre-registration committed before any timed run (`11c0c95`); stock `nvidia_uvm` 6284DA42; 8 GiB array on the 16 GB GPU, no oversubscribed cell; 160 timed runs (16 cells x 10) and a 48-run residency pass (16 cells x 3).", "",
       "**Falsification note:** \"H2 tests a hypothesis formed after seeing H1's K = 1 result. Its K = 1 malloc timing cells repeat a condition already observed; only the new K values, the residency measures and the allocator contrast are tests of a prediction made before the data.\"", "",
       "## Timing (one Holm family of 8; delta = (t0 - t51) / t51)", "",
       "| allocator | K | median t51 (s) | median t0 (s) | difference (s) | delta | MWU p | Holm-adjusted p | Holm-sig | MDE, family alpha (m = 8) | Cohen's d | without outliers (delta s / p) | evidence id |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
for a in C.ALLOCS:
    for k in C.KS:
        t = TT[(a, k)]
        out.append(f"| {a} | {k} | {float(t['median_base']):.4f} | {float(t['median_c6']):.4f} | {float(t['delta_s']):+.4f} | {float(t['delta_pct']):+.2f}% | {float(t['p']):.2e} | {ADJ[(a, k)]:.2e} | {t['holm_sig']} | {float(t['mde_family_s']):.4f} s = {float(t['mde_family_pct']):.2f}% | {float(t['cohen_d']):+.1f} | {float(t['noout_delta_s']):+.4f} / {float(t['noout_p']):.2e} ({t['n_outliers_base']} and {t['n_outliers_arm']} flagged) | `H2.{a}_k{k}.t0_vs_t51` |")
out += ["", "## GPU memory residency (peak minus pre-launch baseline of `memory.used`; n = 3 runs per cell; 8 GiB = 8192 MiB)", "", "| allocator | K | threshold | median (GiB) | range (GiB) | median fraction of 8 GiB | evidence id |", "|---|---|---|---|---|---|---|"]
for r in RC:
    out.append(f"| {r['alloc']} | {r['K']} | {r['threshold']} | {float(r['median_mib']) / 1024:.2f} | {float(r['min_mib']) / 1024:.2f} to {float(r['max_mib']) / 1024:.2f} | {float(r['median_frac']):.3f} | `H2.res.{r['alloc']}.k{r['K']}.t{r['threshold']}` |")
out += ["", "## Expectations", ""] + [f"- **{z['id']}** {z['criterion']}: **{z['outcome']}** ({z['detail']}) `H2.{z['id']}`" for z in Z if z["id"] != "verdict"]
z7 = next(z for z in Z if z["id"] == "Z7")
_rf = {(r["alloc"], int(r["K"]), int(r["threshold"])): float(r["median_frac"]) for r in RC}
out += ["", "## Observations outside the pre-registered criteria", "",
        f"- On **managed** memory the K = 1 residency at threshold 51 is already {_rf[('managed', 1, 51)]:.3f} of the array (`H2.res.managed.k1.t51`), against {_rf[('malloc', 1, 51)]:.3f} on malloc (`H2.res.malloc.k1.t51`): the t0-vs-t51 residency contrast that Z5 expects exists only on HMM. On managed memory the whole array is resident after a K = 1 pass at both thresholds, so its small t0 cost is not a difference in volume moved.",
        f"- Z2 and Z3 failed because the malloc t51 medians are not monotonic in K (K = 512 is faster than K = 64, as in E8/H1); they do not enter the verdict."]
out += ["", "## Limitations", "One platform, one benchmark and page list, four K values, in memory only (HMM oversubscription is not run, see `GATE_H1_REPORT.md`). `memory.used` is a device-level measure; baseline subtraction assumes nothing else changes GPU memory during the run (headless host). Absolute times are not comparable across allocators; only within-allocator contrasts and the difference of deltas are. CS2-N10 and CLAIM_SCOPE are not edited; the proposed claim text is `consolidation/CS2_N12_PROPOSED.md`.", "",
        "## Figures", "`paper/figures/F-H2-time.pdf` (median time against K; t0 blue, t51 grey; managed filled, malloc open markers; every run a point) and `paper/figures/F-H2-res.pdf` (residency against K); CSV fallbacks `F-H2-time.csv`, `F-H2-res.csv`."]
open("results/analysis/gate_e/GATE_H2_REPORT.md", "w").write("\n".join(out) + "\n")
# ---- figures
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import make_paper_figures as M
M.style()
col = {0: M.THR[0], 51: M.THR[51]}
fig, ax = plt.subplots(figsize=(M.COL1 * 1.3, 2.7))
rows_out = []
for a in C.ALLOCS:
    for t in (0, 51):
        xs, ys = [], []
        for i, k in enumerate(C.KS):
            v = [float(r["wall_s"]) for r in RUNS if r["workload"] == f"{a}_k{k}" and r["label"].endswith(f"stock-t{t}")]
            dx = (-0.2 if a == "managed" else 0.2) + (-0.05 if t == 0 else 0.05)
            M.pts(ax, i + dx, v, col[t], "o", jitter=0.03, size=5, alpha=0.5)
            xs.append(i + dx); ys.append(st.median(v))
            for j, x in enumerate(v, 1): rows_out.append([a, k, t, j, f"{x:.6f}"])
        ax.plot(xs, ys, color=col[t], lw=0.8, zorder=4)
        ax.scatter(xs, ys, s=26, marker="o", facecolor=col[t] if a == "managed" else "white", edgecolor=col[t], linewidths=1.1, zorder=5)
ax.set_xticks(range(len(C.KS))); ax.set_xticklabels([str(k) for k in C.KS]); ax.set_xlabel("pages touched per 2 MB block (K)"); ax.set_ylabel("wall-clock (s)")
from matplotlib.lines import Line2D
ax.legend(handles=[Line2D([], [], marker="o", color=M.THR[0], ms=4, lw=0.8, label="threshold 0"), Line2D([], [], marker="o", color=M.THR[51], ms=4, lw=0.8, label="threshold 51 (shipped)"),
                   Line2D([], [], marker="o", ls="", mfc="k", mec="k", ms=4, label="managed (filled)"), Line2D([], [], marker="o", ls="", mfc="w", mec="k", ms=4, label="malloc, HMM (open)")], frameon=False, loc="upper center", bbox_to_anchor=(0.5, -0.25), ncol=2, fontsize=6.3)
fig.tight_layout()
for ext in ("pdf", "png"): fig.savefig(f"paper/figures/F-H2-time.{ext}", bbox_inches="tight", dpi=300)
plt.close(fig)
with open("paper/figures/F-H2-time.csv", "w", newline="") as f:
    w = csv.writer(f); w.writerow(["allocator", "K", "threshold", "run", "wall_s"]); w.writerows(rows_out)
# (C13) the residency figure F-H2-res is now produced by tests/c13_fig_hres.py (managed memory.used is not a valid volume measure; catalog #31)
# ---- CS2-N12 proposal
dm, dg = float(TT[("malloc", 1)]["delta_pct"]), float(TT[("managed", 1)]["delta_pct"])
rf = {(r["alloc"], int(r["K"]), int(r["threshold"])): float(r["median_frac"]) for r in RC}
ci = z7["detail"]
fails = [z["id"] for z in Z if z["id"] in ("Z1", "Z4", "Z6", "Z7") and z["outcome"] == "FAILED"]
d512 = float(TT[("malloc", 512)]["delta_pct"])
if verdict == "MECHANISM SUPPORTED":
    txt = (f"CS2-N12 (HMM, in memory). On `malloc`'d memory under the open driver's HMM mode, lowering `uvm_perf_prefetch_threshold` from 51 to 0 speeds up dense access (Stencil-24K -7.97%, `H1.stencil.stock-t0_vs_stock-t51`; sparse K = 512 {d512:+.2f}%, `H2.malloc_k512.t0_vs_t51`) and slows down sparse access without oversubscription (K = 1 {dm:+.2f}%, `H2.malloc_k1.t0_vs_t51`). "
           f"At threshold 0 the GPU memory made resident by a K = 1 pass is {100 * min(rf[('malloc', 1, 0)], rf[('managed', 1, 0)]):.0f}% or more of the array on both allocators (malloc {100 * rf[('malloc', 1, 0)]:.0f}%, managed {100 * rf[('managed', 1, 0)]:.0f}%; `H2.res.malloc.k1.t0`, `H2.res.managed.k1.t0`), so the volume moved is the same. "
           f"The cost differs: the K = 1 slowdown is {dm:+.2f}% on HMM against {dg:+.2f}% on managed memory (difference and 95% CI: {ci}; `H2.Z7`). This is consistent with HMM's per-4 KB `migrate_vma` migration (Section III). The oversubscribed HMM case was not measured (stock-driver defect, Section V).")
elif verdict == "PARTIAL":
    txt = (f"CS2-N12 (HMM, in memory). On `malloc`'d memory under the open driver's HMM mode, lowering `uvm_perf_prefetch_threshold` from 51 to 0 speeds up dense access (Stencil-24K -7.97%, `H1.stencil.stock-t0_vs_stock-t51`; sparse K = 512 {d512:+.2f}%, `H2.malloc_k512.t0_vs_t51`) and slows down sparse access without oversubscription (K = 1 {dm:+.2f}%, `H2.malloc_k1.t0_vs_t51`). "
           f"The pre-registered mechanism is only partly supported: the criteria that did not hold are {', '.join(fails) or 'none of Z1, Z4, Z6, Z7 (see the report for the verdict path)'} ({'; '.join(z['id'] + ': ' + z['detail'] for z in Z if z['id'] in fails)}). "
           f"K = 1 residency at threshold 0 is malloc {100 * rf[('malloc', 1, 0)]:.0f}% and managed {100 * rf[('managed', 1, 0)]:.0f}% of the array; the K = 1 slowdown is {dm:+.2f}% on HMM against {dg:+.2f}% on managed memory (`H2.Z7`: {ci}). The result is partly consistent with HMM's per-4 KB `migrate_vma` migration (Section III); {', '.join(fails) or 'the failed criterion'} did not hold. The oversubscribed HMM case was not measured (stock-driver defect, Section V).")
else:
    txt = (f"CS2-N12 (HMM, in memory). Dense access gains at threshold 0 on HMM (H1). Sparse in-memory K = 1 is slower at threshold 0 on HMM (H1 +200.52%, H2 {dm:+.2f}%, `H2.malloc_k1.t0_vs_t51`); the explanation tested in H2 (whole-array migration at a higher per-page cost) was refuted by "
           + ("the malloc K = 1 threshold-0 residency of " + f"{100 * rf[('malloc', 1, 0)]:.0f}% of the array (`H2.res.malloc.k1.t0`)" if rf[('malloc', 1, 0)] <= 0.5 else "the threshold-0 times across K (Z1: " + next(z['detail'] for z in Z if z['id'] == 'Z1') + ")") + ". The cause is open.")
open("results/analysis/consolidation/CS2_N12_PROPOSED.md", "w").write(f"# CS2-N12 proposed text (Gate C11; verdict {verdict}; CLAIM_SCOPE.md is not edited)\n\n{txt}\n\nNumbers come from `h2_tests.csv`, `h2_residency_cells.csv` and `h2_z.csv`; H1 numbers from `h1_tests.csv`.\n")
print("report written;", verdict)
